// Normaliza el registro de Airtable (recurrente o recién creado) y arma el contexto
const r = $input.first().json;
const f = r.fields || r;
const e = $('Entrada Unificada').first().json;
const raw = f['Resumen Consolidado'] || '';
let resumenTexto = 'Primera conversación, sin historial previo.';
if (raw) {
  try {
    const j = JSON.parse(raw);
    resumenTexto = `Asunto: ${j.asunto_principal}. Puntos clave: ${(j.puntos_clave || []).join('; ')}. Acción requerida: ${j.accion_requerida}.`;
  } catch (err) {
    resumenTexto = String(raw).slice(0, 1000);
  }
}
return [{ json: {
  canal: e.canal,
  session_id: e.session_id,
  mensaje: e.mensaje,
  from_email: e.from_email || '',
  from_name: e.from_name || '',
  subject: e.subject || '',
  thread_id: e.thread_id || '',
  record_id: r.id,
  user_name: f.Nombre || e.from_name || 'cliente sin nombre registrado',
  estado_caso: f['Estado del Caso'] || 'nuevo',
  last_summary: resumenTexto,
  mensajes: Number(f.Mensajes || 0) + 1
} }];

