// Convierte los mensajes de la memoria de sesión en texto plano para el resumidor
let msgs = [];
for (const it of $input.all()) {
  const j = it.json;
  if (Array.isArray(j.messages)) msgs.push(...j.messages); else msgs.push(j);
}
const lineas = msgs.map(m => {
  if (m.human !== undefined || m.ai !== undefined) {
    return [m.human ? 'Cliente: ' + m.human : null, m.ai ? 'Agente: ' + m.ai : null].filter(Boolean).join('\n');
  }
  const tipo = String(m.type || m.role || (Array.isArray(m.id) ? m.id[m.id.length - 1] : ''));
  const texto = m.content ?? m.text ?? (m.kwargs && m.kwargs.content) ?? '';
  const quien = /human|user/i.test(tipo) ? 'Cliente: ' : /ai/i.test(tipo) ? 'Agente: ' : '';
  return quien + texto;
}).filter(l => l.trim());
const ctx = $('Preparar Contexto de Memoria').first().json;
return [{ json: { historial: lineas.join('\n'), last_summary: ctx.last_summary } }];

// Normaliza la salida del resumidor: parsea, valida claves y aplica valores por defecto
const raw = $json.text ?? $json.output ?? $json.response ?? '';
let d;
try {
  d = JSON.parse(String(raw).replace(/^```json\s*/i, '').replace(/```$/, '').trim());
} catch (e) {
  d = { asunto_principal: 'Resumen no disponible', puntos_clave: [], accion_requerida: 'Revisar la conversación manualmente' };
}
const resumen = {
  asunto_principal: String(d.asunto_principal || 'Sin asunto identificado').slice(0, 200),
  puntos_clave: Array.isArray(d.puntos_clave) ? d.puntos_clave.map(String).slice(0, 6) : [],
  accion_requerida: String(d.accion_requerida || 'Sin acción definida').slice(0, 300)
};
const ctx = $('Preparar Contexto de Memoria').first().json;
const lineaCliente = resumen.puntos_clave.find(p => /^cliente:/i.test(p));
let nombre = lineaCliente ? lineaCliente.replace(/^cliente:\s*/i, '').trim() : '';
if (!nombre || /no informado/i.test(nombre)) nombre = ctx.user_name === 'cliente sin nombre registrado' ? '' : ctx.user_name;
return [{ json: {
  record_id: ctx.record_id,
  nombre,
  resumen_json: JSON.stringify(resumen),
  datos_clave: resumen.puntos_clave.join('\n'),
  accion_requerida: resumen.accion_requerida
} }];

